create or replace function public.admin_delete_room(_room uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not private.is_admin() then raise exception 'not allowed'; end if; delete from public.rooms where id=_room; end; $$;
create or replace function public.admin_delete_post(_post uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not private.is_admin() then raise exception 'not allowed'; end if; delete from public.posts where id=_post; end; $$;
create or replace function public.admin_list_users(_q text) returns table(id uuid,display_name text,display_no bigint,level int,vip_level int,coins bigint,roles text[],created_at timestamptz) language plpgsql stable security definer set search_path='' as $$ begin if not private.is_admin() then raise exception 'not allowed'; end if; return query select p.id,coalesce(p.display_name,p.username)::text,null::bigint,p.level,p.vip_level,coalesce(w.coins,0),coalesce((select array_agg(ar.role) from public.admin_roles ar where ar.user_id=p.id),array[]::text[]),p.created_at from public.profiles p left join public.wallet_balances w on w.user_id=p.id where _q is null or _q='' or p.display_name ilike '%'||_q||'%' or p.username ilike '%'||_q||'%' or p.id::text=_q order by p.created_at desc limit 100; end; $$;
